from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        n = len(nums)
        max_abs = n * 12
        if k < -max_abs or k > max_abs:
            return -1

        OFF = max_abs + 5
        MASK = (1 << (2 * OFF + 1)) - 1

        def shift(bits: int, delta: int) -> int:
            if delta >= 0:
                return (bits << delta) & MASK
            return (bits >> (-delta)) & MASK

        # dp[parity][product] = bitset of reachable alternating sums
        # parity = 0 -> even length, parity = 1 -> odd length
        dp = [[0] * (limit + 1) for _ in range(2)]

        # overflow[parity] = bitset of sums for subsequences with product > limit
        overflow = [0, 0]

        for x in nums:
            new_dp = [dp[0][:], dp[1][:]]
            new_overflow = [overflow[0], overflow[1]]

            # Start a new subsequence with x only
            if x <= limit:
                new_dp[1][x] |= (1 << (x + OFF))
            else:
                new_overflow[1] |= (1 << (x + OFF))

            for parity in (0, 1):
                new_parity = 1 - parity
                delta = x if parity == 0 else -x

                for p, bits in enumerate(dp[parity]):
                    if bits:
                        q = p * x
                        if q <= limit:
                            new_dp[new_parity][q] |= shift(bits, delta)
                        else:
                            new_overflow[new_parity] |= shift(bits, delta)

                bits = overflow[parity]
                if bits:
                    if x == 0:
                        new_dp[new_parity][0] |= bits
                    else:
                        new_overflow[new_parity] |= shift(bits, delta)

            dp = new_dp
            overflow = new_overflow

        target = 1 << (k + OFF)
        for p in range(limit, -1, -1):
            if (dp[0][p] & target) or (dp[1][p] & target):
                return p

        return -1

