def solve():
    input = sys.stdin.readline
    N = int(input().strip())
    S = input().strip()
    T = input().strip()

    mp = {}
    for s, t in zip(S, T):
        si = ord(s) - 97
        ti = ord(t) - 97
        if si in mp:
            if mp[si] != ti:
                print(-1)
                return
        else:
            mp[si] = ti

    if S == T:
        print(0)
        return

    # If both strings use all 26 letters and are different, no empty letter
    # exists to break cycles without merging different final targets.
    if len(set(S)) == 26 and len(set(T)) == 26 and S != T:
        print(-1)
        return

    nonfixed = sum(1 for c, v in mp.items() if c != v)

    visited = [False] * 26
    cycles = 0

    for c in mp:
        if not visited[c]:
            path = []
            cur = c
            while cur in mp and not visited[cur]:
                visited[cur] = True
                path.append(cur)
                cur = mp[cur]
            if cur in path:
                idx = path.index(cur)
                if len(path) - idx >= 2:
                    cycles += 1

    print(nonfixed + cycles)

