def solve():
    data = sys.stdin.read().split()
    if not data:
        return
    T = int(data[0])
    idx = 1
    out = []
    shift = 500000000
    for _ in range(T):
        R = int(data[idx])
        B = int(data[idx + 1])
        idx += 2

        # Necessary and sufficient conditions
        if R % 2 != 0 or (R == 0 and B % 2 != 0):
            out.append("No")
            continue

        out.append("Yes")
        pieces = []

        if R == 0:
            # All blue, B is even
            h = B // 2 - 1
            uv = [(0, 0), (1, 0)]
            for i in range(1, h + 1):
                uv.append((1, i))
            for i in range(h, 0, -1):
                uv.append((0, i))
            for u, v in uv:
                r = u + v
                c = u - v
                pieces.append(('B', r, c))

        elif B == 0:
            # All red, R is even
            h = R // 2 - 1
            verts = [(0, 0), (1, 0)]
            for i in range(1, h + 1):
                verts.append((1, i))
            for i in range(h, 0, -1):
                verts.append((0, i))
            for r, c in verts:
                pieces.append(('R', r, c))

        else:
            # R > 0, B > 0, R is even
            if B % 2 == 0:
                b = B // 2
                blue_verts = [(0, 0)]
                for t in range(1, b + 1):
                    blue_verts.append((t, -t))
                for t in range(b, 0, -1):
                    blue_verts.append((1 + t, 1 - t))

                k = R // 2 - 1
                red_verts = [(2, 0)]
                for i in range(1, k + 1):
                    red_verts.append((2, i))
                red_verts.append((1, k))
                for i in range(k, 0, -1):
                    red_verts.append((0, i))

                for r, c in blue_verts[:-1]:
                    pieces.append(('B', r, c))
                for r, c in red_verts:
                    pieces.append(('R', r, c))

            else:
                b = (B - 1) // 2
                blue_verts = [(0, 0)]
                for t in range(1, b + 1):
                    blue_verts.append((t, -t))
                for t in range(b, -1, -1):
                    blue_verts.append((1 + t, 1 - t))

                k = R // 2 - 1
                red_verts = [(1, 1)]
                for i in range(1, k + 1):
                    red_verts.append((1, 1 + i))
                red_verts.append((0, 1 + k))
                for i in range(k, 0, -1):
                    red_verts.append((0, i))

                for r, c in blue_verts[:-1]:
                    pieces.append(('B', r, c))
                for r, c in red_verts:
                    pieces.append(('R', r, c))

        for color, r, c in pieces:
            out.append(f"{color} {r + shift} {c + shift}")

    sys.stdout.write("\n".join(out))

