class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        intervals = []
        start = 1
        k = 1
        while start <= 10**9:
            end = start * 4 - 1
            intervals.append((start, end, k))
            start *= 4
            k += 1

        def sum_depth(n: int) -> int:
            if n <= 0:
                return 0
            total = 0
            for s, e, k in intervals:
                if s > n:
                    break
                total += k * (min(n, e) - s + 1)
            return total

        def max_depth(n: int) -> int:
            for s, e, k in intervals:
                if n <= e:
                    return k
            return intervals[-1][2]

        ans = 0
        for l, r in queries:
            total = sum_depth(r) - sum_depth(l - 1)
            md = max_depth(r)
            ans += max(md, (total + 1) // 2)

        return ans

