from functools import lru_cache

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        def count(n: int) -> int:
            if n <= 0:
                return 0

            digits = tuple(map(int, str(n)))
            length = len(digits)

            @lru_cache(None)
            def dfs(pos: int, tight: bool, started: bool, digit_sum: int, digit_prod: int) -> int:
                if pos == length:
                    if not started:
                        return 0
                    return 1 if digit_prod % digit_sum == 0 else 0

                limit = digits[pos] if tight else 9
                total = 0

                for d in range(limit + 1):
                    next_tight = tight and (d == digits[pos])

                    if not started and d == 0:
                        total += dfs(pos + 1, next_tight, False, 0, 1)
                    else:
                        total += dfs(
                            pos + 1,
                            next_tight,
                            True,
                            digit_sum + d,
                            digit_prod * d
                        )

                return total

            return dfs(0, True, False, 0, 1)

        return count(r) - count(l - 1)

