class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)

        children = [{}]
        depth = [0]
        cnt = [0]
        term = [None]

        for idx, w in enumerate(words):
            node = 0
            cnt[0] += 1
            for ch in w:
                nxt = children[node].get(ch)
                if nxt is None:
                    nxt = len(children)
                    children[node][ch] = nxt
                    children.append({})
                    depth.append(depth[node] + 1)
                    cnt.append(0)
                    term.append(None)
                node = nxt
                cnt[node] += 1

            if term[node] is None:
                term[node] = [idx]
            else:
                term[node].append(idx)

        sys.setrecursionlimit(300000)

        starts = [[] for _ in range(n + 2)]
        ends = [[] for _ in range(n + 2)]
        order = [0] * (n + 1)

        pos = 0
        globalBest = -1

        def dfs(u: int) -> None:
            nonlocal pos, globalBest

            L = pos + 1
            tl = term[u]
            if tl is not None:
                for idx in tl:
                    pos += 1
                    order[pos] = idx

            for v in children[u].values():
                dfs(v)

            R = pos
            c = cnt[u]
            d = depth[u]

            if c > k:
                if d > globalBest:
                    globalBest = d
            elif c == k:
                if L > 1:
                    starts[1].append(d)
                    ends[L].append(d)
                if R < n:
                    starts[R + 1].append(d)

        dfs(0)

        ans_pos = [0] * (n + 1)
        heap = []
        active = {}

        for p in range(1, n + 1):
            for d in ends[p]:
                active[d] = active.get(d, 0) - 1

            for d in starts[p]:
                active[d] = active.get(d, 0) + 1
                heapq.heappush(heap, -d)

            while heap and active.get(-heap[0], 0) <= 0:
                heapq.heappop(heap)

            cur = -heap[0] if heap else -1
            if globalBest > cur:
                cur = globalBest
            if cur < 0:
                cur = 0

            ans_pos[p] = cur

        ans = [0] * n
        for p in range(1, n + 1):
            ans[order[p]] = ans_pos[p]

        return ans

