class Dinic:
    def __init__(self, n):
        self.n = n
        self.g = [[] for _ in range(n)]

    def add_edge(self, fr, to, cap):
        fwd = [to, cap, len(self.g[to])]
        rev = [fr, 0, len(self.g[fr])]
        self.g[fr].append(fwd)
        self.g[to].append(rev)

    def bfs(self, s, t):
        level = [-1] * self.n
        q = deque([s])
        level[s] = 0
        while q:
            v = q.popleft()
            for e in self.g[v]:
                if e[1] > 0 and level[e[0]] < 0:
                    level[e[0]] = level[v] + 1
                    q.append(e[0])
        self.level = level
        return level[t] >= 0

    def dfs(self, v, t, f):
        if v == t:
            return f
        for i in range(self.it[v], len(self.g[v])):
            self.it[v] = i
            e = self.g[v][i]
            if e[1] > 0 and self.level[v] < self.level[e[0]]:
                ret = self.dfs(e[0], t, min(f, e[1]))
                if ret:
                    e[1] -= ret
                    self.g[e[0]][e[2]][1] += ret
                    return ret
        self.it[v] = len(self.g[v])
        return 0

    def max_flow(self, s, t):
        flow = 0
        INF_FLOW = 10**18
        while self.bfs(s, t):
            self.it = [0] * self.n
            while True:
                f = self.dfs(s, t, INF_FLOW)
                if f == 0:
                    break
                flow += f
        return flow


def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    K = int(next(it))

    edges = []
    for _ in range(M):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        edges.append((u, v))

    def feasible(t):
        if t == 0:
            return True

        Vvar = N * t
        S = Vvar
        T = S + 1
        dinic = Dinic(Vvar + 2)
        INF = 10**9

        def node(v, level):
            # v: 0-based, level: 1..t
            return v * t + (level - 1)

        # d(1) = 0
        for i in range(1, t + 1):
            dinic.add_edge(node(0, i), T, INF)

        # d(N) = t
        for i in range(1, t + 1):
            dinic.add_edge(S, node(N - 1, i), INF)

        # d(v) >= i  =>  d(v) >= i-1
        for v in range(N):
            for i in range(2, t + 1):
                dinic.add_edge(node(v, i), node(v, i - 1), INF)

        for u, v in edges:
            # Cost 1 if d(u) = i-1 and d(v) = i
            for i in range(1, t + 1):
                dinic.add_edge(node(v, i), node(u, i), 1)

            # d(v) <= d(u) + 1
            for i in range(1, t):
                dinic.add_edge(node(v, i + 1), node(u, i), INF)

        flow = dinic.max_flow(S, T)
        return flow <= K

    lo, hi = 0, N - 1
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if feasible(mid):
            lo = mid
        else:
            hi = mid - 1

    print(lo)


