import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    K = data[1]
    V = N * K

    if K == 1:
        print("Yes")
        return

    adj = [[] for _ in range(V + 1)]
    idx = 2
    for _ in range(V - 1):
        u = data[idx]
        v = data[idx + 1]
        idx += 2
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (V + 1)
    parent[1] = -1
    order = [1]

    for v in order:
        for u in adj[v]:
            if u != parent[v]:
                parent[u] = v
                order.append(u)

    state = [0] * (V + 1)

    for v in reversed(order):
        open_children = []
        bad = False

        for u in adj[v]:
            if u == parent[v]:
                continue
            st = state[u]
            if st == -1:
                bad = True
                break
            if st > 0:
                open_children.append(st)

        if bad:
            state[v] = -1
            continue

        cnt = len(open_children)

        if cnt >= 3:
            state[v] = -1
        elif cnt == 2:
            if open_children[0] + open_children[1] + 1 == K:
                state[v] = 0
            else:
                state[v] = -1
        elif cnt == 1:
            length = open_children[0]
            if length + 1 == K:
                state[v] = 0
            elif length + 1 < K:
                state[v] = length + 1
            else:
                state[v] = -1
        else:
            state[v] = 1

    print("Yes" if state[1] == 0 else "No")


