def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    p = data[1:]

    pos = [0] * (n + 1)
    for idx, value in enumerate(p, start=1):
        pos[value] = idx

    bit = [0] * (n + 2)

    def add(i, v):
        while i <= n:
            bit[i] += v
            i += i & -i

    def query(i):
        s = 0
        while i > 0:
            s += bit[i]
            i -= i & -i
        return s

    ans = 0

    for value in range(1, n + 1):
        cur_pos = pos[value]
        smaller_before = query(cur_pos - 1)
        start_pos = smaller_before + 1

        if start_pos < value:
            count = value - start_pos
            ans += (start_pos + value - 1) * count // 2

        add(cur_pos, 1)

    print(ans)

