from typing import List

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        events = [[] for _ in range(n + 1)]
        m = len(conflictingPairs)

        for idx, (a, b) in enumerate(conflictingPairs):
            if a < b:
                x, y = a, b
            else:
                x, y = b, a
            events[y].append((x, idx))

        freq = [0] * (n + 1)

        max_val = 0
        max_count = 0
        max_id = -1
        second_val = 0

        sum_f = 0
        gain = [0] * m

        for r in range(1, n + 1):
            for x, idx in events[r]:
                freq[x] += 1

                if x > max_val:
                    second_val = max_val
                    max_val = x
                    max_count = 1
                    max_id = idx
                elif x == max_val:
                    max_count += 1
                    if max_count > 1:
                        max_id = -1
                else:
                    if x > second_val:
                        second_val = x

            sum_f += max_val

            if max_count == 1 and max_val > 0:
                gain[max_id] += max_val - second_val

        total = n * (n + 1) // 2
        return total - sum_f + max(gain)

import sys

def solve():
    input = sys.stdin.buffer.readline
    line = input()
    if not line:
        return

    N, M = map(int, line.split())
    adj = [[] for _ in range(N)]

    for _ in range(M):
        x, y, z = map(int, input().split())
        x -= 1
        y -= 1
        adj[x].append((y, z))
        adj[y].append((x, z))

    d = [-1] * N
    ans = [0] * N
    BITS = 31

    for s in range(N):
        if d[s] != -1:
            continue

        d[s] = 0
        stack = [s]
        comp = []

        while stack:
            v = stack.pop()
            comp.append(v)
            dv = d[v]

            for to, z in adj[v]:
                nd = dv ^ z
                if d[to] == -1:
                    d[to] = nd
                    stack.append(to)
                else:
                    if d[to] != nd:
                        sys.stdout.write("-1\n")
                        return

        if len(comp) == 1:
            ans[s] = 0
            continue

        counts = [0] * BITS
        for v in comp:
            val = d[v]
            b = 0
            while val:
                if val & 1:
                    counts[b] += 1
                val >>= 1
                b += 1

        root = 0
        n = len(comp)
        for b in range(BITS):
            if counts[b] * 2 > n:
                root |= (1 << b)

        for v in comp:
            ans[v] = root ^ d[v]

    sys.stdout.write(" ".join(map(str, ans)) + "\n")


