class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        pattern = str2

        # Prefix function for KMP
        pi = [0] * m
        for i in range(1, m):
            j = pi[i - 1]
            while j > 0 and pattern[i] != pattern[j]:
                j = pi[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
            pi[i] = j

        # KMP transition table: state s (0..m) after reading one character
        trans = [[0] * 26 for _ in range(m + 1)]
        chars = [chr(i + 97) for i in range(26)]
        for s in range(m + 1):
            for c, ch in enumerate(chars):
                if s == m:
                    j = pi[m - 1] if m > 0 else 0
                else:
                    j = s

                while j > 0 and pattern[j] != ch:
                    j = pi[j - 1]
                if j < m and pattern[j] == ch:
                    j += 1
                trans[s][c] = j

        # trans_mask[s]: bit t is set if some character leads from s to t
        trans_mask = [0] * (m + 1)
        for s in range(m + 1):
            mask = 0
            for c in range(26):
                mask |= 1 << trans[s][c]
            trans_mask[s] = mask

        all_states = (1 << (m + 1)) - 1
        match_bit = 1 << m
        no_match = all_states ^ match_bit

        # allowed[p] is the set of KMP states allowed after reading position p
        allowed = [all_states] * L
        for p in range(m - 1, L):
            i = p - m + 1
            if str1[i] == 'T':
                allowed[p] = match_bit
            else:
                allowed[p] = no_match

        # can[p][s] is a bitmask of states s from which positions p..L-1 can be completed
        can = [0] * (L + 1)
        can[L] = all_states

        for p in range(L - 1, -1, -1):
            valid = can[p + 1] & allowed[p]
            if valid == 0:
                can[p] = 0
                continue

            res = 0
            for s in range(m + 1):
                if trans_mask[s] & valid:
                    res |= 1 << s
            can[p] = res

        if not (can[0] & 1):
            return ""

        # Greedily build the lexicographically smallest string
        ans = []
        s = 0
        for p in range(L):
            valid = can[p + 1] & allowed[p]
            for c in range(26):
                t = trans[s][c]
                if (valid >> t) & 1:
                    ans.append(chars[c])
                    s = t
                    break
            else:
                return ""

        return ''.join(ans)

from typing import List

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        O = (n + 1) // 2
        E = n // 2

        fact = [1] * (n + 1)
        for i in range(1, n + 1):
            fact[i] = fact[i - 1] * i

        if n % 2 == 0:
            total = 2 * fact[O] * fact[E]
        else:
            total = fact[O] * fact[E]

        if k > total:
            return []

        odd = list(range(1, n + 1, 2))
        even = list(range(2, n + 1, 2))
        ans = []

        if n % 2 == 0:
            m = n // 2
            C = fact[m - 1] * fact[m]
            idx = (k - 1) // C
            val = idx + 1
            ans.append(val)

            if val % 2 == 1:
                odd.remove(val)
                start_odd = True
            else:
                even.remove(val)
                start_odd = False

            k -= idx * C
            start_pos = 1
        else:
            start_odd = True
            start_pos = 0

        for pos in range(start_pos, n):
            if start_odd:
                req_odd = (pos % 2 == 0)
            else:
                req_odd = (pos % 2 == 1)

            candidates = odd if req_odd else even

            rem_odd = 0
            for p in range(pos + 1, n):
                if start_odd:
                    if p % 2 == 0:
                        rem_odd += 1
                else:
                    if p % 2 == 1:
                        rem_odd += 1

            rem_even = (n - pos - 1) - rem_odd
            C = fact[rem_odd] * fact[rem_even]

            idx = (k - 1) // C
            val = candidates.pop(idx)
            ans.append(val)
            k -= idx * C

        return ans

import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    N = data[idx]; idx += 1

    W = [0] + data[idx:idx + N]; idx += N

    L = [0] * (N + 1)
    R = [0] * (N + 1)
    for i in range(1, N + 1):
        L[i] = data[idx]
        R[i] = data[idx + 1]
        idx += 2

    Q = data[idx]; idx += 1

    MAXC = 2 * N + 5
    INF = 10**18

    minWL = [INF] * (MAXC + 1)
    minWR = [INF] * (MAXC + 1)

    for i in range(1, N + 1):
        w = W[i]
        if w < minWL[L[i]]:
            minWL[L[i]] = w
        if w < minWR[R[i]]:
            minWR[R[i]] = w

    # prefR[x] = min W with R <= x
    prefR = [INF] * (MAXC + 2)
    cur = INF
    for x in range(1, MAXC + 1):
        if minWR[x] < cur:
            cur = minWR[x]
        prefR[x] = cur

    # suffL[x] = min W with L >= x
    suffL = [INF] * (MAXC + 2)
    cur = INF
    for x in range(MAXC, 0, -1):
        if minWL[x] < cur:
            cur = minWL[x]
        suffL[x] = cur

    # Segment trees for range minimum queries on L and R
    size = 1
    while size <= MAXC:
        size <<= 1

    treeL = [INF] * (2 * size)
    treeR = [INF] * (2 * size)

    for i in range(1, MAXC + 1):
        treeL[size + i] = minWL[i]
        treeR[size + i] = minWR[i]

    for i in range(size - 1, 0, -1):
        left = treeL[2 * i]
        right = treeL[2 * i + 1]
        treeL[i] = left if left < right else right

        left = treeR[2 * i]
        right = treeR[2 * i + 1]
        treeR[i] = left if left < right else right

    def query(tree, l, r):
        if l > r:
            return INF
        l += size
        r += size
        res = INF
        while l <= r:
            if l & 1:
                if tree[l] < res:
                    res = tree[l]
                l += 1
            if not (r & 1):
                if tree[r] < res:
                    res = tree[r]
                r -= 1
            l >>= 1
            r >>= 1
        return res

    out = []
    for _ in range(Q):
        s = data[idx]
        t = data[idx + 1]
        idx += 2

        # Direct edge if intervals are disjoint
        if R[s] < L[t] or R[t] < L[s]:
            ans = W[s] + W[t]
        else:
            Lmin = L[s] if L[s] < L[t] else L[t]
            Rmax = R[s] if R[s] > R[t] else R[t]

            common = prefR[Lmin - 1]
            cr = suffL[Rmax + 1]
            if cr < common:
                common = cr

            ans = INF
            if common < INF:
                ans = W[s] + W[t] + common

            # Length-3 path, possible only when intervals cross
            if L[s] < L[t]:
                i, j = s, t
            elif L[t] < L[s]:
                i, j = t, s
            else:
                i = 0

            if i != 0 and R[i] < R[j]:
                a = query(treeL, R[i] + 1, R[j])
                if a < INF:
                    b = query(treeR, L[i], L[j] - 1)
                    if b < INF:
                        cand = W[s] + W[t] + a + b
                        if cand < ans:
                            ans = cand

            if ans >= INF:
                ans = -1

        out.append(str(ans))

    sys.stdout.write("\n".join(out))

if __name__ == "__main__":
    solve()

import sys

def solve() -> None:
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    T = int(next(it))
    out_lines = []
    for _ in range(T):
        N = int(next(it))
        A = next(it)
        B = next(it)
        S = [i for i, c in enumerate(A) if c == '1']
        Tpos = [i for i, c in enumerate(B) if c == '1']
        n = len(S)
        m = len(Tpos)
        if n < m:
            out_lines.append("-1")
            continue

        # Determine the "good" a1 based on A_val = (S[0]-Tpos[0]) + (S[-1]-Tpos[-1])
        A_val = (S[0] - Tpos[0]) + (S[-1] - Tpos[-1])
        if A_val > 0:
            good = 1
        elif A_val < 0:
            good = 0
        else:
            good = None

        def can(M: int, a1) -> bool:
            i = 0
            parity = a1 if a1 is not None else 0
            for j in range(m):
                t = Tpos[j]
                if i >= n:
                    return False
                if abs(S[i] - t) > M:
                    return False
                max_k = i
                while max_k + 1 < n and S[max_k + 1] <= t + M:
                    max_k += 1
                min_leave = m - j - 1
                limit = n - min_leave - 1
                if max_k > limit:
                    max_k = limit
                if max_k < i:
                    return False
                if j == m - 1:
                    if max_k < n - 1:
                        return False
                    return True

                valid_k = -1
                valid_parity = 0
                cur_parity = parity
                for k in range(i, max_k + 1):
                    if S[k + 1] >= Tpos[j + 1] - M:
                        T_gap = Tpos[j + 1] - t
                        if S[k + 1] - S[k] >= T_gap:
                            Δ = (S[k + 1] - S[k]) - T_gap
                            if a1 is None:
                                valid_k = k
                            else:
                                if Δ == 0:
                                    if cur_parity == 0:
                                        valid_k = k
                                        valid_parity = cur_parity
                                else:
                                    valid_k = k
                                    valid_parity = cur_parity
                    if k < max_k:
                        cur_parity ^= (S[k + 1] - S[k]) & 1
                if valid_k == -1:
                    return False
                k = valid_k
                if a1 is not None:
                    T_gap = Tpos[j + 1] - t
                    Δ = (S[k + 1] - S[k]) - T_gap
                    parity = valid_parity ^ (Δ & 1)
                i = k + 1
            return True

        # Binary search for minimal M (ignoring parity)
        low = 0
        high = N
        if not can(high, None):
            out_lines.append("-1")
            continue
        while low < high:
            mid = (low + high) // 2
            if can(mid, None):
                high = mid
            else:
                low = mid + 1
        M_min = low

        # Check if the good a1 (or either if A_val == 0) can achieve M_min
        if good is None:
            if can(M_min, 0) or can(M_min, 1):
                ans = M_min
            else:
                ans = M_min + 1
        else:
            if can(M_min, good):
                ans = M_min
            else:
                ans = M_min + 1
        out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()

from typing import List
from bisect import bisect_left, bisect_right

class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        S = side
        # side 0: bottom (y=0), param = x
        # side 1: right (x=S), param = y
        # side 2: top (y=S), param = S - x
        # side 3: left (x=0), param = S - y
        sides_points = [[] for _ in range(4)]
        for x, y in points:
            if y == 0:
                sides_points[0].append(x)
            elif x == S:
                sides_points[1].append(y)
            elif y == S:
                sides_points[2].append(S - x)
            elif x == 0:
                sides_points[3].append(S - y)
        for a in sides_points:
            a.sort()

        def check(D: int) -> bool:
            gap = S - D
            arrs = sides_points
            m = [len(a) for a in arrs]
            b = min(range(4), key=lambda i: m[i])
            K = k
            INF = 10 ** 9

            # up_idx[i][c][j] = index of c-th selected point starting at index j on side i
            up_idx = []
            for i in range(4):
                a = arrs[i]
                mi = len(a)
                side_up = [None] * (K + 1)
                if mi == 0:
                    for c in range(1, K + 1):
                        side_up[c] = []
                else:
                    nxt = [0] * mi
                    for j in range(mi):
                        if D == 0:
                            nxt[j] = j + 1
                        else:
                            nxt[j] = bisect_left(a, a[j] + D)
                            if nxt[j] <= j:
                                nxt[j] = j + 1
                    curr = list(range(mi))
                    for c in range(1, K + 1):
                        side_up[c] = curr[:]
                        if c < K:
                            new_curr = [INF] * mi
                            for j in range(mi):
                                nj = nxt[j]
                                if nj < mi:
                                    new_curr[j] = curr[nj]
                            curr = new_curr
                up_idx.append(side_up)

            earliest = []
            for i in range(4):
                e = [INF] * (K + 1)
                if m[i] > 0:
                    for c in range(1, K + 1):
                        e[c] = up_idx[i][c][0]
                earliest.append(e)

            # down_min[c][j] = maximum possible minimum param for c points ending at index j on side b
            a_b = arrs[b]
            mb = len(a_b)
            down_min = [[-1] * mb for _ in range(K + 1)]
            if mb > 0:
                prev = [0] * mb
                for j in range(mb):
                    if D == 0:
                        prev[j] = j - 1
                    else:
                        p = bisect_right(a_b, a_b[j] - D) - 1
                        if p >= j:
                            p = j - 1
                        prev[j] = p
                curr = list(range(mb))
                for c in range(1, K + 1):
                    vals = down_min[c]
                    for j in range(mb):
                        if curr[j] >= 0:
                            vals[j] = a_b[curr[j]]
                    if c < K:
                        new_curr = [-1] * mb
                        for j in range(mb):
                            p = prev[j]
                            if p >= 0:
                                new_curr[j] = curr[p]
                        curr = new_curr

            s0 = (b + 1) % 4
            s1 = (b + 2) % 4
            s2 = (b + 3) % 4

            def precompute_trans(prev_side: int, curr_side: int):
                a_prev = arrs[prev_side]
                a_curr = arrs[curr_side]
                m_prev = len(a_prev)
                m_curr = len(a_curr)
                trans = [[INF] * m_prev for _ in range(K + 1)]
                if m_curr == 0:
                    return trans
                for j in range(m_prev):
                    L = a_prev[j] - gap
                    j_curr = bisect_left(a_curr, L)
                    if j_curr < m_curr:
                        for c in range(1, K + 1):
                            trans[c][j] = up_idx[curr_side][c][j_curr]
                return trans

            trans0 = precompute_trans(b, s0)
            trans1 = precompute_trans(s0, s1)
            trans2 = precompute_trans(s1, s2)

            # Case 1: break side b is empty
            dp_empty = [False] * (K + 1)
            dp_empty[0] = True
            dp_non = [INF] * (K + 1)
            steps = [(trans0, earliest[s0]), (trans1, earliest[s1]), (trans2, earliest[s2])]
            for trans, earliest_c in steps:
                ndp_empty = [False] * (K + 1)
                ndp_non = [INF] * (K + 1)
                for cur in range(K + 1):
                    if dp_empty[cur]:
                        ndp_empty[cur] = True
                        max_c = K - cur
                        for c in range(1, max_c + 1):
                            idx = earliest_c[c]
                            if idx < ndp_non[cur + c]:
                                ndp_non[cur + c] = idx
                    j_prev = dp_non[cur]
                    if j_prev < INF:
                        ndp_empty[cur] = True
                        max_c = K - cur
                        for c in range(1, max_c + 1):
                            idx = trans[c][j_prev]
                            if idx < ndp_non[cur + c]:
                                ndp_non[cur + c] = idx
                dp_empty, dp_non = ndp_empty, ndp_non

            max_rem = -1
            for rem in range(K + 1):
                if dp_empty[rem] or dp_non[rem] < INF:
                    max_rem = rem
            if max_rem >= K:
                return True

            # Case 2: break side b is non-empty
            a_s2 = arrs[s2]
            steps_rem = [(trans1, earliest[s1]), (trans2, earliest[s2])]
            for j0 in range(mb):
                dp_empty = [False] * (K + 1)
                dp_empty[0] = True
                dp_non = [INF] * (K + 1)
                for c in range(1, K + 1):
                    idx = trans0[c][j0]
                    if idx < INF:
                        dp_non[c] = idx

                for trans, earliest_c in steps_rem:
                    ndp_empty = [False] * (K + 1)
                    ndp_non = [INF] * (K + 1)
                    for cur in range(K + 1):
                        if dp_empty[cur]:
                            ndp_empty[cur] = True
                            max_c = K - cur
                            for c in range(1, max_c + 1):
                                idx = earliest_c[c]
                                if idx < ndp_non[cur + c]:
                                    ndp_non[cur + c] = idx
                        j_prev = dp_non[cur]
                        if j_prev < INF:
                            ndp_empty[cur] = True
                            max_c = K - cur
                            for c in range(1, max_c + 1):
                                idx = trans[c][j_prev]
                                if idx < ndp_non[cur + c]:
                                    ndp_non[cur + c] = idx
                    dp_empty, dp_non = ndp_empty, ndp_non

                de, dn = dp_empty, dp_non
                for c0 in range(1, K + 1):
                    min_b = down_min[c0][j0]
                    if min_b < 0:
                        continue
                    rem_needed = K - c0
                    if rem_needed <= 0:
                        return True
                    B = min_b + gap
                    for rem in range(K, rem_needed - 1, -1):
                        if de[rem]:
                            return True
                        idx = dn[rem]
                        if idx < INF and a_s2[idx] <= B:
                            return True
            return False

        lo, hi = 0, S
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if check(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    n = data[0]
    adj = [[] for _ in range(n + 1)]

    idx = 1
    for _ in range(n - 1):
        a = data[idx]
        b = data[idx + 1]
        idx += 2
        adj[a].append(b)
        adj[b].append(a)

    parent = [0] * (n + 1)
    parent[1] = -1
    order = []
    stack = [1]

    while stack:
        v = stack.pop()
        order.append(v)
        for to in adj[v]:
            if to != parent[v]:
                parent[to] = v
                stack.append(to)

    INF = -10**9
    g_any = [0] * (n + 1)
    g_has = [INF] * (n + 1)
    ans = -1

    for v in reversed(order):
        top = []
        max_has = INF

        for to in adj[v]:
            if parent[to] == v:
                val = g_any[to]

                if len(top) < 4:
                    top.append(val)
                    top.sort(reverse=True)
                elif val > top[-1]:
                    top[-1] = val
                    top.sort(reverse=True)

                if g_has[to] > max_has:
                    max_has = g_has[to]

        if len(top) >= 3:
            g_has[v] = 1 + top[0] + top[1] + top[2]
        else:
            g_has[v] = INF

        g_any[v] = g_has[v] if g_has[v] > 1 else 1

        if len(top) >= 4:
            cand = 1 + top[0] + top[1] + top[2] + top[3]
            if cand > ans:
                ans = cand

        if max_has != INF:
            cand = 1 + max_has
            if cand > ans:
                ans = cand

    print(ans if ans > 0 else -1)


if __name__ == "__main__":
    main()

import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    N = int(data[0])
    lines = data[1:1 + N]

    incoming = [[] for _ in range(N)]
    out_mask = [[0] * N for _ in range(26)]

    for i in range(N):
        row = lines[i]
        for j, ch in enumerate(row):
            if ch != 45:  # '-'
                c = ch - 97
                incoming[j].append((i, c))
                out_mask[c][i] |= (1 << j)

    dist = [[-1] * N for _ in range(N)]
    unvisited = [(1 << N) - 1 for _ in range(N)]

    max_len = 2 * N * N + 5
    buckets = [[] for _ in range(max_len)]

    # Empty paths
    for i in range(N):
        dist[i][i] = 0
        unvisited[i] &= ~(1 << i)
        buckets[0].append((i, i))

    # Length-1 palindromes: single edges
    for i in range(N):
        row = lines[i]
        for j, ch in enumerate(row):
            if ch != 45 and i != j:
                if dist[i][j] == -1:
                    dist[i][j] = 1
                    unvisited[i] &= ~(1 << j)
                    buckets[1].append((i, j))

    # BFS over states (a, b): middle palindrome path from a to b
    for d in range(max_len):
        bkt = buckets[d]
        if not bkt:
            continue
        nd = d + 2
        if nd >= max_len:
            continue
        for a, b in bkt:
            for u, c in incoming[a]:
                mask = out_mask[c][b]
                if mask:
                    new = unvisited[u] & mask
                    while new:
                        lsb = new & -new
                        v = lsb.bit_length() - 1
                        dist[u][v] = nd
                        unvisited[u] ^= lsb
                        buckets[nd].append((u, v))
                        new ^= lsb

    out = []
    for i in range(N):
        out.append(' '.join(map(str, dist[i])))
    sys.stdout.write('\n'.join(out))

if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])
        # Directions: DR, DL, UL, UR
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        ans = 0

        for d in range(4):
            dr, dc = dirs[d]

            # pre[r][c] = longest valid straight segment ending at (r, c)
            # while moving in direction d.
            pre = [[0] * m for _ in range(n)]

            # Process cells in forward order along direction d.
            if dr > 0:
                r_iter = range(n)
            else:
                r_iter = range(n - 1, -1, -1)

            if dc > 0:
                c_iter = range(m)
            else:
                c_iter = range(m - 1, -1, -1)

            for r in r_iter:
                row = grid[r]
                pre_row = pre[r]
                for c in c_iter:
                    val = row[c]
                    if val == 1:
                        pre_row[c] = 1
                    elif val == 2:
                        pr, pc = r - dr, c - dc
                        if 0 <= pr < n and 0 <= pc < m:
                            pv = grid[pr][pc]
                            if pv == 1:
                                pre_row[c] = 2
                            elif pv == 0:
                                p = pre[pr][pc]
                                if p:
                                    pre_row[c] = p + 1
                    elif val == 0:
                        pr, pc = r - dr, c - dc
                        if 0 <= pr < n and 0 <= pc < m:
                            pv = grid[pr][pc]
                            if pv == 2:
                                p = pre[pr][pc]
                                if p:
                                    pre_row[c] = p + 1

            # After the turn, the direction becomes clockwise 90 degrees.
            d2 = (d + 1) % 4
            dr2, dc2 = dirs[d2]

            # after0[r][c]: longest alternating sequence starting at (r, c)
            # with first expected value 0 while moving in direction d2.
            # after2[r][c]: same, but first expected value 2.
            after0 = [[0] * m for _ in range(n)]
            after2 = [[0] * m for _ in range(n)]

            # Process cells in reverse order along direction d2.
            if dr2 > 0:
                r_iter2 = range(n - 1, -1, -1)
            else:
                r_iter2 = range(n)

            if dc2 > 0:
                c_iter2 = range(m - 1, -1, -1)
            else:
                c_iter2 = range(m)

            for r in r_iter2:
                row = grid[r]
                a0_row = after0[r]
                a2_row = after2[r]
                for c in c_iter2:
                    val = row[c]
                    nr, nc = r + dr2, c + dc2

                    if 0 <= nr < n and 0 <= nc < m:
                        next0 = after0[nr][nc]
                        next2 = after2[nr][nc]
                    else:
                        next0 = next2 = 0

                    if val == 0:
                        a0_row[c] = 1 + next2
                    elif val == 2:
                        a2_row[c] = 1 + next0

            # Combine a straight prefix ending at (r, c) with a turn.
            for r in range(n):
                pre_row = pre[r]
                for c in range(m):
                    p = pre_row[c]
                    if p:
                        val = grid[r][c]
                        nr, nc = r + dr2, c + dc2
                        extra = 0
                        if 0 <= nr < n and 0 <= nc < m:
                            if val == 2:
                                extra = after0[nr][nc]
                            else:
                                extra = after2[nr][nc]
                        total = p + extra
                        if total > ans:
                            ans = total

        return ans

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        A, B, C = p.split('*')
        n = len(s)
        a, b, c = len(A), len(B), len(C)

        def occurrences(pat: str):
            m = len(pat)
            lps = [0] * m
            j = 0
            for i in range(1, m):
                while j > 0 and pat[i] != pat[j]:
                    j = lps[j - 1]
                if pat[i] == pat[j]:
                    j += 1
                    lps[i] = j

            res = []
            j = 0
            for i, ch in enumerate(s):
                while j > 0 and ch != pat[j]:
                    j = lps[j - 1]
                if ch == pat[j]:
                    j += 1
                    if j == m:
                        res.append(i - m + 1)
                        j = lps[j - 1]
            return res

        INF = 10**18
        ans = INF

        if b > 0:
            Bpos = occurrences(B)
            if not Bpos:
                return -1

            Apos = occurrences(A) if a > 0 else None
            if a > 0 and not Apos:
                return -1

            Cpos = occurrences(C) if c > 0 else None
            if c > 0 and not Cpos:
                return -1

            idxA = -1
            idxC = 0

            for m in Bpos:
                e = m + b

                if a > 0:
                    while idxA + 1 < len(Apos) and Apos[idxA + 1] + a <= m:
                        idxA += 1
                    if idxA < 0:
                        continue
                    i = Apos[idxA]
                else:
                    i = m

                if c > 0:
                    while idxC < len(Cpos) and Cpos[idxC] < e:
                        idxC += 1
                    if idxC == len(Cpos):
                        break
                    j = Cpos[idxC]
                else:
                    j = e

                cand = (j + c) - i
                if cand < ans:
                    ans = cand

        else:
            if a == 0 and c == 0:
                return 0

            if c == 0:
                if a == 0:
                    return 0
                Apos = occurrences(A)
                return a if Apos else -1

            if a == 0:
                Cpos = occurrences(C)
                return c if Cpos else -1

            Apos = occurrences(A)
            Cpos = occurrences(C)
            if not Apos or not Cpos:
                return -1

            idxA = -1
            for j in Cpos:
                while idxA + 1 < len(Apos) and Apos[idxA + 1] + a <= j:
                    idxA += 1
                if idxA < 0:
                    continue
                i = Apos[idxA]
                cand = (j + c) - i
                if cand < ans:
                    ans = cand

        return -1 if ans == INF else ans

