from collections import defaultdict

MOD = 998244353

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:]

    # edges[p][i] = exponent of prime p in A_i
    edges = defaultdict(lambda: [0] * (N - 1))

    for i, a in enumerate(A):
        d = 2
        while d * d <= a:
            if a % d == 0:
                cnt = 0
                while a % d == 0:
                    a //= d
                    cnt += 1
                edges[d][i] = cnt
            d += 1
        if a > 1:
            edges[a][i] = 1

    ans = 1

    for p, e_list in edges.items():
        S = sum(e_list)
        if S == 0:
            continue

        powp = [1] * (S + 1)
        for i in range(1, S + 1):
            powp[i] = (powp[i - 1] * p) % MOD

        # dp0[x]: no zero seen yet, current exponent is x
        # dp1[x]: at least one zero seen, current exponent is x
        dp0 = [0] * (S + 1)
        dp1 = [0] * (S + 1)

        dp1[0] = 1
        for x in range(1, S + 1):
            dp0[x] = powp[x]

        for e in e_list:
            ndp0 = [0] * (S + 1)
            ndp1 = [0] * (S + 1)

            if e == 0:
                for x in range(S + 1):
                    w = powp[x]
                    a0 = dp0[x]
                    if a0:
                        ndp0[x] = (a0 * w) % MOD
                    a1 = dp1[x]
                    if a1:
                        ndp1[x] = (a1 * w) % MOD
            else:
                # x -> x + e
                limit = S - e
                for x in range(limit + 1):
                    y = x + e
                    w = powp[y]
                    a0 = dp0[x]
                    if a0:
                        ndp0[y] = (ndp0[y] + a0 * w) % MOD
                    a1 = dp1[x]
                    if a1:
                        ndp1[y] = (ndp1[y] + a1 * w) % MOD

                # x -> x - e, special case y = 0
                if e <= S:
                    a0 = dp0[e]
                    if a0:
                        ndp1[0] = (ndp1[0] + a0) % MOD
                    a1 = dp1[e]
                    if a1:
                        ndp1[0] = (ndp1[0] + a1) % MOD

                for x in range(e + 1, S + 1):
                    y = x - e
                    w = powp[y]
                    a0 = dp0[x]
                    if a0:
                        ndp0[y] = (ndp0[y] + a0 * w) % MOD
                    a1 = dp1[x]
                    if a1:
                        ndp1[y] = (ndp1[y] + a1 * w) % MOD

            dp0, dp1 = ndp0, ndp1

        F = sum(dp1) % MOD
        ans = (ans * F) % MOD

    print(ans)


