class Solution:
    def countSubstrings(self, s: str) -> int:
        # dp[m][r] = number of substrings ending at the previous position
        # whose value modulo m is r.
        dp = [[0] * m for m in range(10)]
        ans = 0

        for ch in s:
            x = ord(ch) - ord('0')

            for m in range(1, 10):
                old = dp[m]
                new = [0] * m

                for r in range(m):
                    c = old[r]
                    if c:
                        new[(r * 10 + x) % m] += c

                new[x % m] += 1
                dp[m] = new

            if x != 0:
                ans += dp[x][0]

        return ans

from typing import List

class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)
        if n == 1:
            return points[0] if m >= 1 else 0

        def can(x: int) -> bool:
            if x <= 0:
                return True

            moves = 1  # first move: from -1 to 0
            k_prev = 0

            for i in range(n - 1):
                c_i = (x + points[i] - 1) // points[i]

                if i == 0:
                    cur = 1
                else:
                    cur = k_prev + 1

                need = c_i - cur
                if need < 0:
                    need = 0
                k = need

                if i == n - 2:
                    c_last = (x + points[i + 1] - 1) // points[i + 1]
                    if c_last > k:
                        k = c_last - 1
                        moves += 2 * k + 1
                    else:
                        moves += 2 * k
                    return moves <= m
                else:
                    moves += 2 * k + 1
                    if moves > m:
                        return False
                    k_prev = k

            return moves <= m

        low = 0
        high = max(points) * m

        while low < high:
            mid = (low + high + 1) // 2
            if can(mid):
                low = mid
            else:
                high = mid - 1

        return low

