    codes = [ord(ch) for ch in S]

    states = 1 << N

    pop = [0] * states
    for m in range(1, states):
        pop[m] = pop[m >> 1] + (m & 1)

    trans = [[0] * 26 for _ in range(states)]

    for mask in range(states):
        row = [0] * (N + 1)
        for i in range(N):
            row[i + 1] = row[i] + ((mask >> i) & 1)

        tr = trans[mask]
        for c in range(26):
            ch = 97 + c
            new = [0] * (N + 1)

            for i in range(1, N + 1):
                if codes[i - 1] == ch:
                    new[i] = row[i - 1] + 1
                else:
                    a = row[i]
                    b = new[i - 1]
                    new[i] = a if a >= b else b

            nm = 0
            for i in range(1, N + 1):
                if new[i] > new[i - 1]:
                    nm |= 1 << (i - 1)
            tr[c] = nm

    dp = [0] * states
    dp[0] = 1

    for _ in range(M):
        ndp = [0] * states
        for mask, cnt in enumerate(dp):
            if cnt == 0:
                continue
            tr = trans[mask]
            for nxt in tr:
                v = ndp[nxt] + cnt
                if v >= MOD:
                    v -= MOD
                ndp[nxt] = v
        dp = ndp

    ans = [0] * (N + 1)
    for mask, cnt in enumerate(dp):
        if cnt:
            k = pop[mask]
            v = ans[k] + cnt
