def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    it = iter(data)
    N = next(it)
    X = next(it)

    items = [[] for _ in range(4)]
    for _ in range(N):
        v = next(it)
        a = next(it)
        c = next(it)
        items[v].append((c, a))

    dps = []

    for v in range(1, 4):
        dp = [-1] * (X + 1)
        dp[0] = 0

        maxc = 0
        for cost, val in items[v]:
            upper = maxc + cost
            if upper > X:
                upper = X

            for c in range(upper, cost - 1, -1):
                prev = dp[c - cost]
                if prev >= 0:
                    nv = prev + val
                    if nv > dp[c]:
                        dp[c] = nv

            maxc = upper

        for c in range(1, X + 1):
            if dp[c] < dp[c - 1]:
                dp[c] = dp[c - 1]

        dps.append(dp)

    hi = min(dp[X] for dp in dps)
    lo = 0

    while lo < hi:
        mid = (lo + hi + 1) // 2
        total_cost = 0

        for dp in dps:
            needed = bisect_left(dp, mid)
            total_cost += needed
            if total_cost > X:
                break

        if total_cost <= X:
            lo = mid
        else:
            hi = mid - 1

    print(lo)


