import sys

def conv_mod(A, B, mod):
    n = len(A)
    m = len(B)
    res = [0] * (n + m - 1)
    for i, ai in enumerate(A):
        if ai:
            for j, bj in enumerate(B):
                res[i + j] = (res[i + j] + ai * bj) % mod
    return res


def conv_mul(poly, H, factor, mod):
    n = len(poly)
    m = len(H)

    if n == 1:
        val = poly[0]
        if factor != 1:
            val = (val * factor) % mod
        return [(val * h) % mod for h in H]

    if m == 1:
        val = H[0]
        if factor != 1:
            val = (val * factor) % mod
        return [(val * p) % mod for p in poly]

    res = [0] * (n + m - 1)
    for i in range(n):
        pi = poly[i]
        if pi:
            for j in range(m):
                res[i + j] += pi * H[j]

    if factor == 1:
        for i in range(len(res)):
            res[i] %= mod
    else:
        for i in range(len(res)):
            res[i] = (res[i] % mod) * factor % mod
    return res


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    N = int(data[0])
    P = int(data[1])

    n = N // 2
    T = N - 1
    maxM = N * (N - 1) // 2
    L = n

    # binomial coefficients modulo P up to maxM
    C = [[0] * (maxM + 1) for _ in range(maxM + 1)]
    for i in range(maxM + 1):
        C[i][0] = 1
        C[i][i] = 1
        for j in range(1, i):
            C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % P

    # H_table[a][b] = coefficients of
    # ((1+x)^a - 1)^b * (1+x)^{C(b,2)} shifted by b
    H_table = [[None] * (L + 1) for _ in range(L + 1)]

    for a in range(1, L + 1):
        f = [0] * (a + 1)
        for i in range(1, a + 1):
            f[i] = C[a][i]

        pow_f = [1]
        for b in range(1, L + 1):
            pow_f = conv_mod(pow_f, f, P)
            s = b * (b - 1) // 2
            binom = C[s][:s + 1]
            G = conv_mod(pow_f, binom, P)
            H_table[a][b] = G[b:]

    dp = [dict() for _ in range(T + 1)]
    # state: (odd_used, even_used, prev_layer_size, next_type)
    # next_type: 0 = odd, 1 = even
    dp[0][(0, 0, 1, 0)] = [1]

    for u in range(T + 1):
        cur = dp[u]
        if not cur:
            continue

        for (o, e, a, t), poly in cur.items():
            if o == n and e == n - 1:
                continue

            rem = T - u
            if t == 0:
                cap = n - o
            else:
                cap = (n - 1) - e

            maxb = cap if cap < rem else rem
            for b in range(1, maxb + 1):
                if t == 0:
                    new_o = o + b
                    new_e = e
                else:
                    new_o = o
                    new_e = e + b

                new_t = 1 - t
                new_key = (new_o, new_e, b, new_t)
                H = H_table[a][b]
                factor = C[rem][b]

                conv = conv_mul(poly, H, factor, P)
                target = dp[u + b]
                existing = target.get(new_key)

                if existing is None:
                    target[new_key] = conv
                else:
                    if len(existing) < len(conv):
                        existing.extend([0] * (len(conv) - len(existing)))
                    for i, val in enumerate(conv):
                        nv = existing[i] + val
                        if nv >= P:
                            nv -= P
                        existing[i] = nv

        dp[u] = None

    final = dp[T]
    ans_len = maxM - T + 1
    ans = [0] * ans_len

    for poly in final.values():
        for i, val in enumerate(poly):
            if i >= ans_len:
                break
            nv = ans[i] + val
            if nv >= P:
                nv -= P
            ans[i] = nv

    print(' '.join(map(str, ans)))


