import sys

def mat_mul(A, B, mod):
    n = len(A)
    BT = [[B[i][j] for i in range(n)] for j in range(n)]
    C = [[0] * n for _ in range(n)]
    for i in range(n):
        Ai = A[i]
        Ci = C[i]
        for j in range(n):
            Bj = BT[j]
            s = 0
            for k in range(n):
                s += Ai[k] * Bj[k]
            Ci[j] = s % mod
    return C

def mat_pow(F, exp, mod):
    n = len(F)
    result = [[0] * n for _ in range(n)]
    for i in range(n):
        result[i][i] = 1 % mod
    base = [row[:] for row in F]
    e = exp
    while e:
        if e & 1:
            result = mat_mul(result, base, mod)
        e >>= 1
        if e:
            base = mat_mul(base, base, mod)
    return result

