from typing import List

class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)

        # parent[i] = first index j > i with nums[j] > nums[i], or n if none
        parent = [n] * n
        stack = []
        for i in range(n - 1, -1, -1):
            val = nums[i]
            while stack and nums[stack[-1]] <= val:
                stack.pop()
            if stack:
                parent[i] = stack[-1]
            else:
                parent[i] = n
            stack.append(i)

        # prefW[i] = sum of contributions of nodes on the path i -> parent[i] -> ...
        prefW = [0] * (n + 1)
        for i in range(n - 1, -1, -1):
            p = parent[i]
            if p < n:
                w = nums[i] * (p - i)
            else:
                w = 0
            prefW[i] = w + prefW[p]

        # Binary lifting over parent pointers
        LOG = (n + 1).bit_length()
        up = [[n] * (n + 1) for _ in range(LOG)]
        for i in range(n):
            up[0][i] = parent[i]
        up[0][n] = n

        for j in range(1, LOG):
            prev = up[j - 1]
            curr = up[j]
            for i in range(n + 1):
                curr[i] = prev[prev[i]]

        # Prefix sums of nums
        pref = [0] * (n + 1)
        for i in range(n):
            pref[i + 1] = pref[i] + nums[i]

        rev = range(LOG - 1, -1, -1)
        ans = 0
        l = 0

        for r in range(n):
            while True:
                # Find the last left-to-right maximum in nums[l..r]
                node = l
                for j in rev:
                    anc = up[j][node]
                    if anc <= r:
                        node = anc
                last = node

                # Sum of running maxima in nums[l..r]
                F = prefW[l] - prefW[last] + nums[last] * (r - last + 1)
                cost = F - (pref[r + 1] - pref[l])

                if cost <= k:
                    break
                l += 1

            ans += r - l + 1

        return ans

