def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    A = int(next(it))
    B = int(next(it))

    intervals = []
    for _ in range(M):
        L = int(next(it))
        R = int(next(it))
        intervals.append((L, R))

    # Any bad interval of length >= B cannot be crossed.
    for L, R in intervals:
        if R - L + 1 >= B:
            print("No")
            return

    if A == B:
        # Only moves of exactly A are possible.
        if N % A != 1 % A:
            print("No")
            return
        rem = 1 % A
        for L, R in intervals:
            if A == 1:
                print("No")
                return
            x = L + ((rem - L) % A)
            if x <= R:
                print("No")
                return
        print("Yes")
        return

    # A < B
    Bval = B
    full_mask = (1 << Bval) - 1
    low_mask = (1 << (Bval - A + 1)) - 1
    LIMIT = 500

    mask = 0

    def sim_good(S, T, mask):
        length = T - S + 1
        if length <= 0:
            return mask

        if length <= LIMIT:
            for x in range(S, T + 1):
                if x == 1:
                    new = 1
                else:
                    new = 1 if (mask & low_mask) else 0
                mask = (mask >> 1) | (new << (Bval - 1))
            return mask
        else:
            end_sim = S + LIMIT - 1
            for x in range(S, end_sim + 1):
                if x == 1:
                    new = 1
                else:
                    new = 1 if (mask & low_mask) else 0
                mask = (mask >> 1) | (new << (Bval - 1))
                if mask == full_mask:
                    return full_mask
            return 0

    def sim_bad(L, R, mask):
        for _ in range(L, R + 1):
            mask >>= 1
        return mask

    prev_end = 0
    for L, R in intervals:
        S = prev_end + 1
        T = L - 1
        if S <= T:
            mask = sim_good(S, T, mask)
        mask = sim_bad(L, R, mask)
        prev_end = R

    S = prev_end + 1
    T = N
    if S <= T:
        mask = sim_good(S, T, mask)

    if (mask >> (Bval - 1)) & 1:
        print("Yes")
    else:
        print("No")


