        return

    N, K = data[0], data[1]
    A = data[2:2 + N]

    total_xor = 0
    for x in A:
        total_xor ^= x

    if K <= N - K:
        M = K
        use_chosen = True
    else:
        M = N - K
        use_chosen = False

    best = -1

    def dfs(start, depth, cur_xor):
        nonlocal best

        if depth == M:
            val = cur_xor if use_chosen else (total_xor ^ cur_xor)
            if val > best:
                best = val
            return

        remaining = M - depth
        end = N - remaining + 1

        for i in range(start, end):
            dfs(i + 1, depth + 1, cur_xor ^ A[i])

    dfs(0, 0, 0)
    print(best)

if __name__ == "__main__":
    main()

