import sys
import heapq

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    H, W, X = data[0], data[1], data[2]
    P, Q = data[3] - 1, data[4] - 1
    vals = data[5:]

    n = H * W
    start = P * W + Q
    visited = bytearray(n)
    visited[start] = 1

    cur = vals[start]
    heap = []

    # Push initial adjacent cells
    r, c = P, Q
    if r > 0:
        np = start - W
        heapq.heappush(heap, (vals[np], np))
    if r + 1 < H:
        np = start + W
        heapq.heappush(heap, (vals[np], np))
    if c > 0:
        np = start - 1
        heapq.heappush(heap, (vals[np], np))
    if c + 1 < W:
        np = start + 1
        heapq.heappush(heap, (vals[np], np))

    while heap:
        v, pos = heapq.heappop(heap)
        if visited[pos]:
            continue

        if cur > X * v:
            visited[pos] = 1
            cur += v

            r = pos // W
            c = pos - r * W

            if r > 0:
                np = pos - W
                if not visited[np]:
                    heapq.heappush(heap, (vals[np], np))
            if r + 1 < H:
                np = pos + W
                if not visited[np]:
                    heapq.heappush(heap, (vals[np], np))
            if c > 0:
                np = pos - 1
                if not visited[np]:
                    heapq.heappush(heap, (vals[np], np))
            if c + 1 < W:
                np = pos + 1
                if not visited[np]:
                    heapq.heappush(heap, (vals[np], np))
        else:
            break

    print(cur)

