    solve()

import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:1 + N]

    max_sum = 2 * max(A)
    ans = 0
    k = 0

    while (1 << k) <= max_sum:
        M = 1 << (k + 1)
        mask = M - 1
        target = 1 << k

        cnt = {}
        sums = {}

        for a in A:
            r = a & mask
            if r in cnt:
                cnt[r] += 1
                sums[r] += a
            else:
                cnt[r] = 1
                sums[r] = a

        total = 0

        for r, c in cnt.items():
            s = (target - r) & mask

            if r < s:
                c2 = cnt.get(s)
                if c2 is not None:
                    total += sums[r] * c2 + sums[s] * c
            elif r == s:
                total += (c + 1) * sums[r]

        ans += total >> k
        k += 1

    sys.stdout.write(str(ans))

