import sys

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return

    N = data[0]
    A = data[1:1 + N]

    left = [-1] * N
    right = [-1] * N
    parent = [-1] * N
    stack = []

    # Build max Cartesian tree. Ties are broken by larger index.
    for i in range(N):
        ai = A[i]
        last = -1
        while stack and A[stack[-1]] <= ai:
            last = stack.pop()
        if last != -1:
            left[i] = last
            parent[last] = i
        if stack:
            right[stack[-1]] = i
            parent[i] = stack[-1]
        stack.append(i)

    root = stack[0]

    # Preorder for parent-before-child processing.
    order = []
    st = [root]
    while st:
        v = st.pop()
        order.append(v)
        lc = left[v]
        rc = right[v]
        if lc != -1:
            st.append(lc)
        if rc != -1:
            st.append(rc)

    # S[v] = sum of the subtree interval of v.
    S = A[:]
    for v in reversed(order):
        lc = left[v]
        rc = right[v]
        if lc != -1:
            S[v] += S[lc]
        if rc != -1:
            S[v] += S[rc]

    # up[v] = highest ancestor reachable after v has absorbed its whole subtree.
    up = [0] * N
    up[root] = root
    for v in order:
        p = parent[v]
        if p != -1:
            if S[v] > A[p]:
                up[v] = up[p]
            else:
                up[v] = v

    ans = [0] * N
    for v in range(N):
        av = A[v]
        ignite = False
        if v > 0 and A[v - 1] < av:
            ignite = True
        elif v + 1 < N and A[v + 1] < av:
            ignite = True

        if ignite:
            ans[v] = S[up[v]]
        else:
            ans[v] = av

    sys.stdout.write(' '.join(map(str, ans)) + '\n')


if __name__ == "__main__":
    solve()

from typing import List

class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        T = threshold

        parent = list(range(T + 1))
        rank = [0] * (T + 1)

        def find(x: int) -> int:
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a: int, b: int) -> None:
            ra, rb = find(a), find(b)
            if ra == rb:
                return
            if rank[ra] < rank[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            if rank[ra] == rank[rb]:
                rank[ra] += 1

        for x in nums:
            if x <= T:
                for m in range(x, T + 1, x):
                    union(x, m)

        roots = set()
        large_isolated = 0

        for x in nums:
            if x <= T:
                roots.add(find(x))
            else:
                large_isolated += 1

        return len(roots) + large_isolated
